        return (False, None)
n_max = assign['n_max']
max_ratio = assign['max_ratio']
weights = assign['weights']
# Basic domain checks
if not isinstance(n_max, int) or n_max < 3:
    # Need at least up to 3 to make it nontrivial
    return (False, None)
if not isinstance(max_ratio, int) or max_ratio <= 1:
    return (False, None)
if not isinstance(weights, list) or len(weights) != n_max:
    return (False, None)
if any((not isinstance(w, int) or w <= 0) for w in weights):
