    sum_c = sum(c_prefix)
    sum_ck_km1 = sum(c_prefix[i-1] * (i-1) for i in range(1, n+1))
    # Use the integer-scaled exponent to avoid floating errors
    E2 = 2 * sum_ck_km1 - (n-1) * sum_c
    if E2 >= 0:
        S.append(n)
# Enforce nontriviality: at least one included and one excluded
